#include <stdlib.h>

__attribute__((noinline)) long deref(int idx) {
    if (idx < 0) return 42;
    volatile int *p = (int *)(void *)0;
    return p[idx];
}

__attribute__((noinline)) int trigger(int idx) {
    volatile int acc = 0;
    acc += (int)deref(idx);
    return acc + 1;
}

int main(int argc, char **argv) {
    int idx = 32;
    if (argc > 1) idx = atoi(argv[1]);
    return trigger(idx);
}
